def _plan_listing_request(path):
    check_deadline(source_deadline)
    borrowed=None
    if type(path) is int:
        value=os.readlink('/proc/self/fd/'+str(path));guardpath(value)
        before=identity(os.fstat(path))
        if os.readlink('/proc/self/fd/'+str(path))!=value or identity(os.fstat(path))!=before:
            raise RuntimeError('Source-plan listing descriptor changed before admission')
        borrowed=(path,value,before);original=None
    else:
        original='.' if path is None else os.fspath(path)
        value=os.path.abspath(os.fsdecode(original));guardpath(value)
    if value==root or value.startswith(root+'/'):
        raise PermissionError('Forbidden model directory enumeration refused')
    if value!=str(model) and not value.startswith(_model_prefix):return None
    relative='' if value==str(model) else value[len(_model_prefix):]
    if relative not in _plan_listing_directories:
        raise PermissionError('ROOT listing outside the exact source-plan directories refused')
    return value,original,borrowed

class _PlanDirectory:
    """One fresh nofollow/noatime descriptor chain; no directory-result cache."""
    def __init__(self,value,borrowed=None):
        guardpath(value)
        relative=value[len(_model_prefix):] if value.startswith(_model_prefix) else None
        if relative not in _plan_listing_directories:
            raise PermissionError('Undeclared source-plan directory lease refused')
        self.value=value;self.borrowed=borrowed;self.held=[];self.fd=None;self.closed=False
    def __enter__(self):
        flags=os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW|os.O_NOATIME
        try:
            parent=None;absolute=''
            for part in ('/',*self.value.strip('/').split('/')):
                check_deadline(source_deadline)
                opened=os.open(part,flags) if parent is None else os.open(part,flags,dir_fd=parent)
                absolute='/' if parent is None else absolute.rstrip('/')+'/'+part
                self.held.append((opened,absolute,part,None))
                shape=os.fstat(opened)
                self.held[-1]=(opened,absolute,part,identity(shape))
                if not stat.S_ISDIR(shape.st_mode):raise RuntimeError('Source-plan parent is not an ordinary directory')
                parent=opened
            self.fd=parent;self.full10=self.held[-1][3]
            self.check()
            _plan_active_listing_fds[self.fd]=self
            return self
        except BaseException as primary:
            self.close(primary);raise
    def check(self):
        try:
            for position,(fd,absolute,part,before) in enumerate(self.held):
                check_deadline(source_deadline);guardpath(absolute)
                if identity(os.fstat(fd))!=before or os.readlink('/proc/self/fd/'+str(fd))!=absolute:
                    raise RuntimeError('Source-plan directory descriptor custody changed')
                if position:
                    # Only the known single child of the held named parent; bypass
                    # no source guard and never follow any parent/leaf symlink.
                    named=_plan_native_stat(part,dir_fd=self.held[position-1][0],follow_symlinks=False)
                    if identity(named)!=before:raise RuntimeError('Source-plan named parent custody changed')
            if self.borrowed is not None and self.fd is not None:
                fd,value,before=self.borrowed
                if os.readlink('/proc/self/fd/'+str(fd))!=value or identity(os.fstat(fd))!=before or before!=self.full10:
                    raise RuntimeError('Source-plan caller directory descriptor custody changed')
        except OSError as refused:
            raise RuntimeError('Source-plan held directory custody unavailable') from refused
    def close(self,primary=None):
        if self.closed:return
        self.closed=True;errors=[]
        try:self.check()
        except BaseException as error:errors.append(error)
        if self.fd is not None and _plan_active_listing_fds.get(self.fd) is self:
            del _plan_active_listing_fds[self.fd]
        for fd,_,_,_ in reversed(self.held):
            try:os.close(fd)
            except BaseException as error:errors.append(error)
        self.held=[]
        if errors:
            if primary is not None:
                for error in errors:primary.add_note('Transport directory cleanup/custody also refused: '+type(error).__name__)
            else:
                for error in errors[1:]:errors[0].add_note('Additional transport cleanup refusal: '+type(error).__name__)
                raise RuntimeError('Source-plan owned directory custody/cleanup refused') from errors[0]
    def __exit__(self,kind,primary,traceback):
        self.close(primary);return False

def _plan_audit_listing_fd(fd):
    value=os.readlink('/proc/self/fd/'+str(fd));guardpath(value)
    if value==root or value.startswith(root+'/'):
        raise PermissionError('Forbidden model descriptor enumeration refused')
    if value==str(model) or value.startswith(_model_prefix):
        lease=_plan_active_listing_fds.get(fd)
        if lease is None or lease.closed or lease.value!=value:
            raise PermissionError('Only active owned source-plan directory enumeration is allowed')
        # Registry membership is authorization only; all identities are fresh.
        lease.check()

class _PlanDirEntry:
    """Rebase only a real native name; every requested shape is a fresh lstat."""
    def __init__(self,name,original,parent,parent_full10):
        guardpath(name)
        self._raw_name=name;self._parent=parent;self._parent_full10=parent_full10
        self._name=os.fsencode(name) if isinstance(original,bytes) else name
        self._path=self._name if original is None else os.path.join(original,self._name)
    @property
    def name(self):return self._name
    @property
    def path(self):return self._path
    def __fspath__(self):return self._path
    def stat(self,*,follow_symlinks=True):
        try:
            full=self._parent+'/'+self._raw_name;guardpath(full)
            relative=full[len(_model_prefix):]
            _model_relative(full,directory=relative in _model_directories)
            with _PlanDirectory(self._parent) as lease:
                if lease.full10!=self._parent_full10:raise RuntimeError('Source-plan entry parent changed after enumeration')
                shape=_plan_native_stat(self._raw_name,dir_fd=lease.fd,follow_symlinks=False)
                if follow_symlinks and stat.S_ISLNK(shape.st_mode):
                    raise RuntimeError('Source-plan symlink entry refused before following its target')
                return shape
        except OSError as refused:
            if refused.errno is not None:raise
            raise RuntimeError('Source-plan entry carrier admission refused; no skipped subtree') from refused
    def inode(self):return self.stat(follow_symlinks=False).st_ino
    def is_symlink(self):
        try:return stat.S_ISLNK(self.stat(follow_symlinks=False).st_mode)
        except FileNotFoundError:return False
    def is_dir(self,*,follow_symlinks=True):
        try:return stat.S_ISDIR(self.stat(follow_symlinks=follow_symlinks).st_mode)
        except FileNotFoundError:return False
    def is_file(self,*,follow_symlinks=True):
        try:return stat.S_ISREG(self.stat(follow_symlinks=follow_symlinks).st_mode)
        except FileNotFoundError:return False

class _PlanScandir:
    def __init__(self,request):
        value,self.original,borrowed=request
        self.lease=_PlanDirectory(value,borrowed);self.lease.__enter__()
        try:self.native=_plan_native_scandir(self.lease.fd)
        except BaseException as primary:self.lease.close(primary);raise
        self.count=0;self.closed=False
    def __iter__(self):return self
