    def __next__(self):
        if self.closed:raise StopIteration
        try:
            check_deadline(source_deadline)
            entry=next(self.native);guardpath(entry.name)
            self.count+=1
            if self.count>_plan_entry_limit:
                # RuntimeError is intentional: os.walk must not swallow a
                # carrier bound/custody refusal as an ordinary missing tree.
                raise RuntimeError('Source-plan directory entry bound exceeded; no truncation')
            return _PlanDirEntry(entry.name,self.original,self.lease.value,self.lease.full10)
        except StopIteration:
            self.close();raise
        except BaseException as primary:
            self.close(primary)
            if isinstance(primary,OSError) and primary.errno is None:
                raise RuntimeError('Source-plan iterator carrier refusal; no omitted tree') from primary
            raise
    def close(self,primary=None):
        if self.closed:return
        self.closed=True;cleanup_error=None
        try:self.native.close()
        except BaseException as error:
            if primary is not None:primary.add_note('Native directory iterator cleanup also refused: '+type(error).__name__)
            else:cleanup_error=error
        self.lease.close(primary if primary is not None else cleanup_error)
        if primary is None and cleanup_error is not None:
            raise RuntimeError('Source-plan owned directory iterator cleanup refused') from cleanup_error
    def __exit__(self,kind,primary,traceback):
        self.close(primary);return False

def _plan_noatime_scandir(path=None):
    try:
        request=_plan_listing_request(path)
        return _plan_native_scandir(path) if request is None else _PlanScandir(request)
    except OSError as refused:
        if refused.errno is not None:raise
        raise RuntimeError('Source-plan scandir carrier admission refused; no omitted tree') from refused

def _plan_noatime_listdir(path=None):
    request=_plan_listing_request(path)
    if request is None:return _plan_native_listdir(path)
    with _PlanScandir(request) as entries:
        # Every actual native name, in native order; no manifest-made listing,
        # filtering, hidden extras, or cached absence/membership acceptance.
        return [entry.name for entry in entries]

